import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ExampleComponent } from './example/example.component';
import { Generator as GeneratorComponent } from './generator/generator.component';
import { Renderer as RendererComponent } from './renderer/renderer.component';

@Component({
  selector: 'mf-forms-lib',
  templateUrl: './mf-forms.component.html',
  standalone: true,
  imports: [
    CommonModule,
    ExampleComponent,
    GeneratorComponent,
    RendererComponent
  ],
  styleUrls: ['./mf-forms.component.scss'],
})
export class FormsComponent { 
  constructor(
  ) {}
  ngOnInit(): void {
  };
};
